(function(root){'use strict';
const G=root.Construction;
function camera(p,v){const q=G.sub(p,[v.x,v.y,v.z]),a=v.yaw,b=v.pitch,t=Math.sin(a)*q[0]+Math.cos(a)*q[1];return [Math.cos(a)*q[0]-Math.sin(a)*q[1],Math.cos(b)*t-Math.sin(b)*q[2],Math.sin(b)*t+Math.cos(b)*q[2]];}
function direction(v){return [Math.sin(v.pitch)*Math.sin(v.yaw),Math.sin(v.pitch)*Math.cos(v.yaw),Math.cos(v.pitch)];}
function faces(q){if(q.type==='tetrahedron')return [[0,1,2],[0,1,3],[0,2,3],[1,2,3]].map(f=>f.map(i=>q.p[i]));if(['prism','hexahedron'].includes(q.type))return [[0,1,2,3],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]].map(f=>f.map(i=>q.p[i]));if(q.type==='triangle')return [q.p];if(q.type==='plane'){const [a,b,c]=q.p,u=G.sub(b,a),v=G.sub(c,a);return [[G.sub(G.sub(a,G.mul(u,.25)),G.mul(v,.25)),G.add(G.sub(a,G.mul(v,.25)),G.mul(u,1.25)),G.add(G.add(a,G.mul(u,1.25)),G.mul(v,1.25)),G.add(G.sub(a,G.mul(u,.25)),G.mul(v,1.25))]];}return [];}
function edges(q){if(q.type==='tetrahedron')return [[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]].map(e=>e.map(i=>q.p[i]));if(['prism','hexahedron'].includes(q.type))return [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]].map(e=>e.map(i=>q.p[i]));return [];}
function scene(values,v){const triangles=[],spheres=[];for(const q of values){if(q.error||q.visible===false)continue;if(q.type==='sphere')spheres.push({id:q.id,c:camera(q.c,v),r:q.radius});for(const face of faces(q)){const p=face.map(x=>camera(x,v));for(let i=1;i<p.length-1;i++)triangles.push([p[0],p[i],p[i+1]]);}}return {triangles,spheres};}
// The viewer is at positive camera depth. Strict depth comparison avoids self-occluding edges.
function hidden(p,s){const tol=1e-7*Math.max(1,...p.map(Math.abs));for(const [a,b,c] of s.triangles){const den=(b[1]-c[1])*(a[0]-c[0])+(c[0]-b[0])*(a[1]-c[1]);if(Math.abs(den)<1e-12)continue;const u=((b[1]-c[1])*(p[0]-c[0])+(c[0]-b[0])*(p[1]-c[1]))/den,w=((c[1]-a[1])*(p[0]-c[0])+(a[0]-c[0])*(p[1]-c[1]))/den,t=1-u-w;if(Math.min(u,w,t)>=-1e-9&&u*a[2]+w*b[2]+t*c[2]>p[2]+tol)return true;}for(const s0 of s.spheres){const d2=(p[0]-s0.c[0])**2+(p[1]-s0.c[1])**2;if(d2<s0.r*s0.r&&s0.c[2]+Math.sqrt(s0.r*s0.r-d2)>p[2]+tol)return true;}return false;}
function split(a,b,v,s){const ca=camera(a,v),cb=camera(b,v),length=Math.hypot(cb[0]-ca[0],cb[1]-ca[1])*v.scale,n=Math.max(2,Math.min(1200,Math.ceil(length/3))),runs=[];let start=0,prior=hidden(G.add(ca,G.mul(G.sub(cb,ca),.5/n)),s);for(let i=1;i<n;i++){const h=hidden(G.add(ca,G.mul(G.sub(cb,ca),(i+.5)/n)),s);if(h!==prior){runs.push({a:G.add(a,G.mul(G.sub(b,a),start/n)),b:G.add(a,G.mul(G.sub(b,a),i/n)),hidden:prior});start=i;prior=h;}}runs.push({a:G.add(a,G.mul(G.sub(b,a),start/n)),b,hidden:prior});return runs;}
function fromScreen(x,y,v,W,H,plane='xy',level=0){const rx=(x-W/2)/v.scale,ry=-(y-H/2)/v.scale,a=v.yaw,b=v.pitch,right=[Math.cos(a),-Math.sin(a),0],up=[Math.cos(b)*Math.sin(a),Math.cos(b)*Math.cos(a),-Math.sin(b)],n=direction(v),base=G.add([v.x,v.y,v.z],G.add(G.mul(right,rx),G.mul(up,ry))),axis={xy:2,xz:1,yz:0}[plane];if(Math.abs(n[axis])<1e-5)throw Error('Mặt phẳng đặt điểm đang nhìn nghiêng 90°. Chọn góc nhìn tương ứng hoặc xoay hình để đặt điểm.');return G.add(base,G.mul(n,(level-base[axis])/n[axis]));}
root.ConstructionView={camera,direction,faces,edges,scene,hidden,split,fromScreen};if(typeof module!=='undefined')module.exports=root.ConstructionView;
})(typeof window!=='undefined'?window:globalThis);
